'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const gardens=[[[2,6],[3,4]],[[1,8],[2,4]],[[2,8],[4,4]],[[3,8],[4,6]],[[1,6],[2,3]],[[1,4],[2,2]]];
let variant=OrionProgress.variant('measures'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,width=1,height=1,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function measure(w=width,h=height){return {area:w*h,perimeter:2*(w+h)};}
function challenge(v=variant,s=stage){const first=measure(...gardens[v][0]);if(s===2)return{area:first.area,perimeter:first.perimeter,more:true};return {...measure(...gardens[v][s]),more:false};}
function matches(q=challenge(),w=width,h=height){if(!Number.isInteger(w)||!Number.isInteger(h)||w<1||h<1||w>8||h>8)return false;const m=measure(w,h);return m.perimeter===q.perimeter&&(q.more?m.area>q.area:m.area===q.area);}
function setDimension(axis,value){if(solved||!['width','height'].includes(axis)||!Number.isInteger(value)||value<1||value>8)return;if(axis==='width')width=value;else height=value;state='ready';render();}
function resetTrial(){width=height=1;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('measures')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(!matches())state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('measure');}render();if(solved&&stage<2)$('next').focus();}
function drawing(){let cells='';for(let y=0;y<8;y++)for(let x=0;x<8;x++)cells+=`<rect x="${30+x*28}" y="${20+y*28}" width="28" height="28" fill="${x<width&&y<height?'#4e9b78':'#183c3c'}" stroke="#8caaa2" stroke-width="1"/>`;return `<svg viewBox="0 0 290 274" role="img" aria-label="${t(`${width} by ${height} garden; ${width*height} soil squares`,`${width} 乘 ${height} 的花圃；${width*height} 格泥土`)}">${cells}<rect x="30" y="20" width="${width*28}" height="${height*28}" fill="none" stroke="#ffdc81" stroke-width="5"/><text x="142" y="266" text-anchor="middle" fill="#ffe1a1">${t('Width','寬度')} ${width} ↔</text><text x="8" y="135" fill="#ffe1a1">${height}</text></svg>`;}
function hints(){return[t('Count the green squares for soil. Walk all the way around the gold edge for fencing. They measure different things.','數綠色方格是泥土面積；沿金色邊線走一圈是圍欄周界。它們量度的東西不同。'),t('Rows × columns counts the squares. For the fence, add all four sides, not just two.','行數 × 列數可數出方格。圍欄要加上四條邊，不只是兩條。'),t(`The two neighbouring side lengths must add to ${challenge().perimeter/2}. Try pairs with that sum and compare their soil areas.`,`相鄰兩條邊的長度相加必須是 ${challenge().perimeter/2}。試不同組合，比較泥土面積。`)];}
function render(){const q=challenge(),m=measure(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Garden of Measures · Orion','量度花園 · Orion');$('stageTitle').textContent=t(`Garden ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 塊花圃 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Garden seals · ${p} / 3`,`花園封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();for(const axis of ['width','height']){$(axis).value=axis==='width'?width:height;$(axis).disabled=solved;$(axis+'Value').textContent=$(axis).value;}
$('goal').textContent=q.more?t(`Use exactly ${q.perimeter} fence units, but enclose MORE than ${q.area} square units of soil.`,`用剛好 ${q.perimeter} 單位的圍欄，但泥土面積要大於 ${q.area} 平方單位。`):t(`Make ${q.area} square units of soil with exactly ${q.perimeter} fence units.`,`泥土面積要有 ${q.area} 平方單位，圍欄剛好 ${q.perimeter} 單位。`);$('area').textContent=m.area;$('perimeter').textContent=m.perimeter;$('comparison').textContent=stage===1?t('Same soil area as garden 1. Can you use less fence?','泥土面積與第一塊相同。能用更少圍欄嗎？'):stage===2?t('Same fence length as garden 1. Can you enclose more soil?','圍欄長度與第一塊相同。能圍出更多泥土嗎？'):t('Green squares fill the inside; gold follows the edge.','綠色方格填滿裏面，金色沿着外圍。');
$('feedback').textContent=state==='success'?t('Both measurements fit. A garden seal shines!','兩項量度都符合，花園封印亮起了！'):state==='wrong'?t('Check both the soil area and the fence length. Reshape the plot and try again.','檢查泥土面積和圍欄長度。改變花圃形狀，再試一次。'):t('Move either slider and watch both measurements change.','移動滑桿，觀察兩項量度怎樣改變。');$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('measure')?t('Measure Sigil saved in your collection.','量度符印已存入收藏。'):'';}
for(const axis of ['width','height'])$(axis).oninput=e=>setDimension(axis,Number(e.target.value));$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('measures',variant);observedVariant=OrionProgress.variant('measures');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('measure');render();};function syncProgress(){const v=OrionProgress.variant('measures'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('measure')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
